-- Every company's documents carry its own brand, set in Settings → Company: a logo, a title
-- ("KEBO") and a line under it ("INTERNATIONAL TRADE"), above its name and its name in Chinese.
-- Nothing of any one company stays in the code: the settings' defaults become blank, so Kebo's
-- details, which were those defaults, are written into Kebo's own settings first (what it has
-- stored wins), with its logo as on keboint.com (240 px) and its title.

UPDATE "settings" s
SET "value" = '{"name": "Shandong Kebo International Trade Co., Ltd.", "nameLocal": "山东科波国际贸易有限公司", "address": "No.5, Jielu Road, High-Tech Zone, City Jining, Shandong, China", "phone": "+86-151-54754812  +86-178-53758700", "email": "shandongkeboint@gmail.com", "website": "www.keboint.com", "taxNo": "91370811MAK4PH5B1N", "bankDetails": "ACCOUNT NAME: SHANDONG KEBO INTERNATIONAL TRADE CO., LTD.\nBANK NAME: BANK OF CHINA RENCHENG SUB BRANCH\nBANK ADDRESS: B.O.C TOWER,1 TAIBAI ROAD JINING, SHANDONG, P, R. CHINA,\nPOST CODE: 272000\nSWIFT CODE: BKCHCNBJ500\nACCOUNT NO: 242895006310", "proformaPrefix": "KEB"}'::jsonb
    || s."value"
    || CASE WHEN s."value" ? 'logo' THEN '{}'::jsonb ELSE '{"brandMark": "KEBO", "brandTagline": "INTERNATIONAL TRADE", "logo": "data:image/webp;base64,"}'::jsonb END
FROM "companies" c
WHERE c."id" = s."company_id" AND c."slug" = 'kebo' AND s."key" = 'company';
